from pathlib import Path
import gzip, base64
p=Path(__file__).resolve().parent
html='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><style>
:root{font-family:var(--font-sans,system-ui);color:var(--foreground,#dde7ef)}body{margin:0}canvas{width:100%;height:440px;display:block;border-radius:12px;background:linear-gradient(150deg,#182632,#091219);touch-action:none}.tools{display:flex;gap:12px;flex-wrap:wrap;align-items:center;padding:12px 0}button{background:var(--secondary,#263c4c);color:inherit;border:1px solid var(--border,#587080);border-radius:7px;padding:8px 12px;cursor:pointer}label{font-size:13px}p{line-height:1.5;font-size:14px;color:var(--muted-foreground,#8199aa)}.legend{display:flex;flex-wrap:wrap;gap:16px;font-size:13px}.a{color:#ff9b42}.b{color:#39c5a2}</style></head><body>
<div class="tools"><button id="play">Animate gait</button><button id="reset">Reset view</button><label><input id="cover" type="checkbox" checked> Brain deck</label><label><input id="hardware" type="checkbox" checked> Hardware envelopes</label></div>
<canvas id="view"></canvas><div class="tools"><label>Crank phase <input id="phase" type="range" min="0" max="360" value="30"></label><span id="degrees">30°</span></div>
<div class="legend"><span class="a">Orange: three-bar foot</span><span class="b">Mint: two-bar foot</span><span>Blue: protective chassis</span></div>
<p>Drag to orbit · Scroll to zoom. Both feet span beneath the body for support. Equal sprockets synchronize the shafts; opposite-side cranks are 180° apart. Hardware blocks and chain are layout envelopes, not detailed supplier CAD.</p><p><b>Prototype:</b> 24 mm lift range; parts fit a 256 mm bed. Animation shows prescribed motion relative to the chassis, not a physics simulation. Verify motor/battery fit before a full print.</p>
<script>(async()=>{const DATA=JSON.parse(await new Response(new Blob([Uint8Array.from(atob('__DATA__'),c=>c.charCodeAt(0))]).stream().pipeThrough(new DecompressionStream('gzip'))).text());
const canvas=document.getElementById('view'),ctx=canvas.getContext('webgl',{antialias:true});let yaw=-0.65,pitch=0.65,zoom=1,phase=30,playing=false,last=0;
const cover=document.getElementById('cover'),hardware=document.getElementById('hardware'),slider=document.getElementById('phase');
function proj(v,w,h){let x=v[0],y=v[1],z=v[2]-55;let a=x*Math.cos(yaw)-y*Math.sin(yaw),b=x*Math.sin(yaw)+y*Math.cos(yaw);let d=b*Math.cos(pitch)-z*Math.sin(pitch),u=b*Math.sin(pitch)+z*Math.cos(pitch);let s=Math.min(w/310,h/260)*zoom;return [w/2+a*s,h/2-u*s,d];}
function shader(type,source){let s=ctx.createShader(type);ctx.shaderSource(s,source);ctx.compileShader(s);return s}const program=ctx.createProgram();ctx.attachShader(program,shader(ctx.VERTEX_SHADER,'attribute vec3 p;attribute vec3 c;varying vec3 col;void main(){gl_Position=vec4(p,1.0);col=c;}'));ctx.attachShader(program,shader(ctx.FRAGMENT_SHADER,'precision mediump float;varying vec3 col;void main(){gl_FragColor=vec4(col,1.0);}'));ctx.linkProgram(program);ctx.useProgram(program);const buffer=ctx.createBuffer();ctx.bindBuffer(ctx.ARRAY_BUFFER,buffer);for(const [n,offset] of [['p',0],['c',12]]){let loc=ctx.getAttribLocation(program,n);ctx.enableVertexAttribArray(loc);ctx.vertexAttribPointer(loc,3,ctx.FLOAT,false,24,offset)}ctx.enable(ctx.DEPTH_TEST);
function draw(){let w=canvas.clientWidth,h=440,dpr=devicePixelRatio||1;if(canvas.width!==w*dpr){canvas.width=w*dpr;canvas.height=h*dpr;}ctx.viewport(0,0,canvas.width,canvas.height);ctx.clearColor(.045,.075,.1,1);ctx.clear(ctx.COLOR_BUFFER_BIT|ctx.DEPTH_BUFFER_BIT);let vertices=[],a=phase*Math.PI/180;
for(const m of DATA){if(!cover.checked&&(m.name==='brain_deck'||m.name==='REF_brain_envelope'||m.name==='REF_screen'))continue;if(!hardware.checked&&(m.name.startsWith('REF_')||m.name.startsWith('steel')))continue;
let vv=m.v.map(v=>{let t=v.slice();if(m.name==='left_foot'){t[0]+=12*Math.cos(a)-12;t[2]+=12*Math.sin(a);}if(m.name==='right_foot'){t[0]+=-12*Math.cos(a)+12;t[2]-=12*Math.sin(a);}if(m.name.startsWith('crank_')){let bits=m.name.split('_'),cx=Number(bits[2]),dx=t[0]-cx,dz=t[2]-54;t[0]=cx+dx*Math.cos(a)-dz*Math.sin(a);t[2]=54+dx*Math.sin(a)+dz*Math.cos(a);}return proj(t,w,h);});
for(let f of m.f){let A=m.v[f[0]],B=m.v[f[1]],C=m.v[f[2]],u=B.map((v,i)=>v-A[i]),v=C.map((v,i)=>v-A[i]),n=[u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]],len=Math.hypot(...n)||1,shade=.55+.3*Math.abs(n[2])/len+.15*Math.abs(n[0])/len;
for(let i of f){let t=vv[i];vertices.push(t[0]*2/w-1,1-t[1]*2/h,t[2]/500,...m.color.map(c=>c*shade/255));}}}
ctx.bufferData(ctx.ARRAY_BUFFER,new Float32Array(vertices),ctx.DYNAMIC_DRAW);ctx.drawArrays(ctx.TRIANGLES,0,vertices.length/6);document.getElementById('degrees').textContent=Math.round(phase)+'°';}
let drag=null;canvas.onpointerdown=e=>{drag=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!drag)return;yaw+=(e.clientX-drag[0])*.008;pitch=Math.max(-.2,Math.min(1.5,pitch+(e.clientY-drag[1])*.008));drag=[e.clientX,e.clientY];draw()};canvas.onpointerup=()=>drag=null;canvas.onwheel=e=>{e.preventDefault();zoom=Math.max(.5,Math.min(2,zoom*Math.exp(-e.deltaY*.001)));draw()};
slider.oninput=()=>{phase=Number(slider.value);draw()};cover.onchange=hardware.onchange=draw;document.getElementById('reset').onclick=()=>{yaw=-.65;pitch=.65;zoom=1;draw()};document.getElementById('play').onclick=()=>{playing=!playing;document.getElementById('play').textContent=playing?'Pause gait':'Animate gait'};
function loop(t){if(playing){phase=(phase+Math.min(t-last,100)*.04)%360;slider.value=phase;draw()}last=t;requestAnimationFrame(loop)}window.onresize=draw;draw();requestAnimationFrame(loop);
})();</script></body></html>'''
(p/'walker_preview.html').write_text(html.replace('__DATA__',base64.b64encode(gzip.compress((p/'mesh_data.json').read_bytes())).decode()))
